/* ─── Repuestos de Pañol por equipo ──────────────────────────
   Relación equipo ↔ materiales de pañol (código SAP). Origen: revisión
   cruzada de planillas de "Alta de Materiales" / repuestos críticos de
   Termomecánica (SAP, Thyssen, Van der Lande, Westric, Lennox, LG, TEAM,
   flota) contra el catálogo de pañol (assets/js/panol-data.js), hecha el
   2026-09-04. Bloques con nota "a confirmar" señalan una ambigüedad real
   en la documentación fuente — ver aviso entregado al usuario.

   2026-09-07: segunda carga automática para equipos de aire. Filtros de
   aire, correas y motores de alimentación/retorno tomados de las fichas
   técnicas UTA (assets/js/uta-specs.js): la medida/modelo se matcheó
   contra el catálogo SAP y la cantidad es el número entre paréntesis de
   la ficha ("600x600x50 (2)" → qty 2). Notas con "ficha técnica UTA"
   marcan esta procedencia; `opciones` lista los otros códigos SAP de la
   misma medida (filtros); "código SAP a confirmar" (cod que empieza con
   "?") = sin match exacto; "confirmar calidad" = la medida sólo existe en
   MERV10/13; los motores son el genérico W22 por potencia. Filtros
   "LAVABLES" no se cargaron.

   2026-09-08: carga masiva de Patio de valijas (303 entradas MEQ…).
   Materiales tomados de los campos "Repuesto motor/rodillo/rodamiento/
   banda SAP" de PATIO_EXTRA (assets/js/patio-extra.js) — ya cruzados
   contra el catálogo SAP el 2026-09-04. La nota lleva el prefijo de
   categoría (Motor / Rodillo / Rodamiento / Banda). NO editar estas
   entradas a mano: regenerar desde PATIO_EXTRA si cambia la fuente.

   Forma de cada entrada (BOM del equipo):
     { equipo: "AAC2115",
       materiales: [ { cod: "20089275", qty: 2, opciones: ["20090001"],
                       nota: "filtro rodete (opcional)" } ] }

   `cod` referencia PANOL_DATA[].cod — la descripción, la UM y el stock se
   resuelven en vivo al renderizar. `qty` es la cantidad necesaria por
   equipo (opcional; si falta se asume 1). `opciones` es un array de
   códigos SAP alternativos equivalentes (opcional). Se edita desde el
   modo administrador (pestaña "Repuestos por equipo" de Pañol /
   Repuestos) o reemplazando este archivo entero. */

